 "content": "from collections import Counter


def transform(grid):
    """Retain large, dense rectangular fields, erasing sparse markers and clutter."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    for color in {v for row in grid for v in row if v != bg}:
        ps = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                ps[r + 1][c + 1] = ps[r][c + 1] + ps[r + 1][c] - ps[r][c] + (grid[r][c] == color)
        def ncolor(r0, r1, c0, c1):
            return ps[r1+1][c1+1] - ps[r0][c1+1] - ps[r1+1][c0] + ps[r0][c0]
        candidates = []
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                rh = r1 - r0 + 1
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        cw = c1 - c0 + 1
                        area = rh * cw
                        n = ncolor(r0, r1, c0, c1)
                        if n * 5 < area * 4:
                            continue
                        if any(ncolor(r, r, c0, c1) * 2 < cw for r in range(r0, r1 + 1)):
                            continue
                        if any(ncolor(r0, r1, c, c) * 2 < rh for c in range(c0, c1 + 1)):
                            continue
                        candidates.append((area, n, r0, r1, c0, c1))
        candidates.sort(reverse=True)
        chosen = []
        for cand in candidates:
            area, n, r0, r1, c0, c1 = cand
            if any(max(0, min(r1, b)-max(r0, a)+1) * max(0, min(c1, e)-max(c0, d)+1) >= area * .8
                   for _, _, a, b, d, e in chosen):
                continue
            chosen.append(cand)
        for _, _, r0, r1, c0, c1 in chosen:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = color
    return out


